style.css:
@-moz-document domain("perplexity.ai") {
@font-face {
    font-family: 'JetBrains Mono';
    src: url(https://fonts.gstatic.com/s/jetbrainsmono/v13/tDbY2o-flEEny0FZhsfKu5WU4zr3E_BX0PnT8RD8yKxTOlOV.woff2) format('woff2');
  }
  body, .erp-tab-p-0 {
    background: url('https://wallpapercave.com/wp/wp13506455.jpg') no-repeat center center fixed;
    background-size: cover;
  }
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(10, 20, 40, 0.35);
    z-index: -1;
    pointer-events: none;
  }
  .scrollbar-subtle::-webkit-scrollbar {
    width: 10px;
    background: transparent;
  }
  .scrollbar-subtle::-webkit-scrollbar-track {
    background-color: rgba(0, 0, 50, 0.2);
    border-radius: 10px;
  }
  .scrollbar-subtle::-webkit-scrollbar-thumb {
    background: linear-gradient(135deg, #1e90ff, #00bfff);
    border-radius: 10px;
    border: 1px solid rgba(0, 191, 255, 0.5);
    box-shadow: 0 0 6px rgba(30, 144, 255, 0.7), 0 0 12px rgba(0, 191, 255, 0.5);
    transition: all 0.3s ease;
  }
  .scrollbar-subtle::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(135deg, #00bfff, #1e90ff);
    box-shadow: 0 0 10px rgba(0, 191, 255, 0.9), 0 0 20px rgba(30, 144, 255, 0.7);
  }
  .prose.text-pretty, div[id*="markdown-content"] .prose {
    background: transparent !important;
    -webkit-backdrop-filter: blur(20px) saturate(120%);
    backdrop-filter: blur(20px) saturate(120%);
    box-shadow: none !important;
    border: none !important;
    border-radius: 18px;
    padding: 24px;
    margin-bottom: 20px;
  }
  .sticky-tabs-ref {
    background: rgba(24, 25, 28, 0.75);
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  }
  .codeWrapper.text-light {
    background: rgba(28, 29, 33, 0.9);
    -webkit-backdrop-filter: blur(14px);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
  }
  div[class*="group/query"] {
    background: rgba(22, 23, 25, 0.6);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 16px;
    padding: 12px;
  }
  .scrollbar-subtle.custom-scroll {
    background: rgba(28, 29, 32, 0.75) !important;
    -webkit-backdrop-filter: blur(18px) saturate(110%);
    backdrop-filter: blur(18px) saturate(110%);
    padding: 12px !important;
    margin: -12px !important;
    border-radius: 12px;
  }
  p, span, div, h1, h2, h3 {
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.6);
  }
  [contenteditable="true"], [contenteditable="true"] * {
    text-shadow: none;
  }
  .bg-base, .bg-transparent, .isolate.mx-auto {
    background: transparent;
    background-color: transparent;
  }
  .bg-raised {
    background-color: rgba(30, 31, 34, 0.75) !important;
    transition: background-color 0.3s ease;
  }
  .bg-base.custom-shadow {
    background: rgba(28, 29, 32, 0.7) !important;
    -webkit-backdrop-filter: blur(16px) saturate(110%);
    backdrop-filter: blur(16px) saturate(110%);
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3) !important;
  }
  .erp-tab-p-0 {
    padding: 0 !important;
  }
}
